  "direct et concret. 3 à 8 phrases ou une courte liste à puces, sauf si on te demande un programme ou une explication détaillée.": "direct and concrete. 3 to 8 sentences or a short bulleted list, unless you're asked for a program or a detailed explanation.",
  "direct, précis et structuré. Adapte la longueur à la question : quelques phrases pour une question simple ; pour un programme, une analyse de séance ou une explication, développe avec des titres courts (###), des puces et des chiffres précis (séries, reps, charges en kg, RPE, repos, grammes). Pas de tableaux (l'app ne les affiche pas) : préfère des listes. Pas de généralités ni de remplissage : chaque phrase doit servir.": "direct, precise and structured. Match the length to the question: a few sentences for a simple question; for a program, a workout analysis or an explanation, go into detail with short headings (###), bullet points and precise numbers (sets, reps, weights in kg, RPE, rest, grams). No tables (the app can't display them): use lists instead. No generalities or filler: every sentence must count.",
