  "L'adresse n'est pas sur ce téléphone. Crée-en une nouvelle pour (re)faire le raccourci : l'ancienne cessera de marcher.": "The address isn't on this phone. Create a new one to (re)build the Shortcut: the old one will stop working.",
  "L'analyse de": "Analysis by",
  "L'analyse de photo demande l'IA en ligne (comptes en ligne + connexion).": "Photo analysis requires online AI (online account + connection).",
  "L'analyse vidéo passe par l'IA en ligne : il faut un compte en ligne et une connexion. En attendant, le bouton « Vérifier ma technique » corrige ta posture en direct, sans internet.": "Video analysis relies on the online AI: you need an online account and a connection. In the meantime, the “Check my form” button corrects your posture live, without internet.",
  "L'ancienne cessera de marcher : il faudra la remplacer dans ton raccourci.": "The old one will stop working: you'll need to replace it in your Shortcut.",
  "L'app calcule chaque série (charge et reps), annonce la série « au max », et fait avancer le programme après chaque séance. Les jours d'entraînement de ta semaine suivent le programme.": "The app works out every set (weight and reps), calls out the “AMRAP” set, and moves the program forward after each workout. The training days in your week follow the program.",
  "L'app exécute automatiquement certaines demandes : créer une séance, modifier le programme de la semaine, l'objectif, la couleur de l'app, le mode clair, la taille du texte, la voix… Si l'utilisateur veut une modification de ce genre, donne-lui la phrase exacte à envoyer, par exemple : « Crée une séance dos de 45 min », « Mets Legs le mercredi », « Passe l'app en bleu », « Mode clair », « Agrandis le texte ».": "The app carries out some requests automatically: creating a workout, changing the weekly program, the goal, the app color, light mode, text size, the voice… If the user wants a change like that, give them the exact sentence to send, for example: “Create a 45-min back workout”, “Put Legs on Wednesday”, “Make the app blue”, “Light mode”, “Bigger text”.",
  "L'autre main pousse doucement le coude.": "Your other hand gently pushes the elbow.",
  "L'IA analyse ta technique…": "The AI is analyzing your form…",
