  "la fonction installée sur Supabase est le code d'exemple, pas celle de GREATNESS": "the function installed on Supabase is the sample code, not GREATNESS's",
  "La force vient du calme.": "Strength comes from calm.",
  "La liaison avec Apple Santé passe par ton compte en ligne : connecte-toi avec un compte en ligne pour l'activer.": "Linking with Apple Health goes through your online account: sign in with an online account to enable it.",
  "la page du projet": "the project page",
  "La prochaine fois, un regard suffit : plus besoin de taper ton code. Rien ne quitte ton téléphone, et ton code marche toujours.": "Next time, a glance is all it takes: no more typing your PIN. Nothing leaves your phone, and your PIN always works.",
  "la prochaine fois.": "next time.",
  "La progression linéaire la plus solide : on monte à chaque séance, et quand ça coince, on change de palier au lieu de s'arrêter.": "The most solid linear progression: you go up every workout, and when you stall, you move to the next stage instead of stopping.",
  "La reconnaissance vocale n'est pas disponible sur ce navigateur.": "Voice recognition isn't available in this browser.",
  "La régularité bat le talent quand le talent ne s'entraîne pas.": "Consistency beats talent when talent doesn't train.",
  "La régularité compte plus que l'intensité.": "Consistency matters more than intensity.",
  "La régularité, c'est mon super-pouvoir préféré.": "Consistency is my favorite superpower.",
  "La régularité, voilà mon secret.": "Consistency, that's my secret.",
  "La salle abandonnée": "The abandoned gym",
  "La séance « Mobilité » (15 min) est parfaite les jours off ; je la place le dimanche dans ton programme.": "The “Mobility” workout (15 min) is perfect on rest days; I put it on Sunday in your program.",
  "La série « 1+ » décide de la suite : 2-3 reps → +2,5 kg ; 4-5 → +2,5 à 5 kg ; 6 et plus → +5 à 7,5 kg ; 0-1 → on garde.": "The “1+” set decides what's next: 2–3 reps → +2.5 kg; 4–5 → +2.5 to 5 kg; 6 or more → +5 to 7.5 kg; 0–1 → keep the same.",
  "La série « 1+ » décide de la suite.": "The “1+” set decides what comes next.",
