  "Le cadrage montre ta photo précédente en transparence et lance un retardateur pour que tu aies le temps de te placer.": "The frame shows your previous photo as a see-through overlay and starts a self-timer so you have time to get in position.",
  "Le calme est une force.": "Calm is a strength.",
  "Le cardio complète bien la muscu": "Cardio is a great complement to lifting",
  "Le chargement s'est arrêté avant la fin : le téléphone a sans doute manqué de mémoire. J'ai choisi le modèle": "Loading stopped before it finished: the phone probably ran out of memory. I switched to the smaller model",
  "Le chargement s'est arrêté avant la fin (app fermée, écran verrouillé ou mémoire pleine). Ferme les autres apps, garde l'écran allumé et réessaie : le téléchargement reprend où il s'était arrêté.": "Loading stopped before it finished (app closed, screen locked or memory full). Close your other apps, keep the screen on and try again: the download picks up where it left off.",
  "Le chemin est beau aujourd'hui. On y va ?": "The trail looks beautiful today. Shall we go?",
  "Le classement et les défis entre amis demandent les comptes en ligne. En attendant, invite tes amis à installer l'app.": "The leaderboard and challenges with friends require online accounts. In the meantime, invite your friends to install the app.",
  "Le coach adapte la suite": "The coach adapts what comes next",
  "Le coach analyse ta séance…": "The coach is analyzing your workout…",
  "le coach sportif de l'app GREATNESS. L'athlète est EN PLEINE SÉANCE, entre deux séries : réponds en 2 à 4 phrases, concrètes et directes, en français et en tutoyant. Pour changer la charge d'un exercice de la séance (en cours": "the fitness coach of the GREATNESS app. The athlete is MID-WORKOUT, between two sets: answer in 2 to 4 sentences, concrete and direct, in English and informally. To change the weight of an exercise in the workout (current",
  "le coach sportif de l'app GREATNESS. Réponds en français, en tutoyant, avec des chiffres précis et un ton motivant.": "the fitness coach of the GREATNESS app. Answer in English, informally, with precise numbers and a motivating tone.",
  "le coach sportif de l'app GREATNESS. Ta personnalité": "the fitness coach of the GREATNESS app. Your personality",
  "Le coach te parle pendant la séance": "The coach talks to you during the workout",
  "Le code doit faire 4 à 6 chiffres.": "The PIN must be 4 to 6 digits.",
  "Le code fait 6 caractères.": "The code is 6 characters long.",
  "Le compte reste en ligne": "The account stays online",
  "Le compte, ses séances et ses stats seront supprimés de ce téléphone. Irréversible.": "The account, its workouts and its stats will be deleted from this phone. This can't be undone.",
  "Le conseil du coach": "Coach's tip",
  "Le duo": "The duo",
  "Le duo à distance passe par ton compte en ligne.": "Remote duo works through your online account.",
  "Le fichier arrive par mail ou dans l'app Fichiers : touche « Choisir un fichier » ci-dessous et sélectionne-le.": "The file arrives by email or in the Files app: tap “Choose a file” below and select it.",
  "Le gardien du dojo": "The dojo guardian",
  "Le grand tournoi commence. Les meilleurs athlètes de la ville sont là, et la Flemme a parié contre toi. Trois records, et la médaille est à toi.": "The big tournament is about to begin. The city's best athletes are here, and Laziness has bet against you. Three PRs, and the medal is yours.",
  "Le kettlebell redescend entre les jambes": "The kettlebell swings back down between your legs",
  "Le maître de la technique": "The master of technique",
  "Le marché": "The market",
  "Le matin à jeun, après les toilettes. C'est la tendance qui compte, pas le chiffre d'un jour.": "First thing in the morning, fasted, after using the bathroom. The trend is what counts, not a single day's number.",
  "le modèle de téléphone et l'écran ouvert, pour comprendre plus vite.": "the phone model and the screen you have open, so we can understand faster.",
  "Le modèle Équilibré est trop lourd pour la plupart des téléphones. J'ai choisi le modèle Léger : touche « Activer l'IA ».": "The Balanced model is too heavy for most phones. I switched to the Light model: tap “Enable AI”.",
  "Le mouvement": "The movement",
  "Le mouvement vient des hanches, pas des bras.": "The movement comes from your hips, not your arms.",
  "Le muscle grandit au repos. Respire.": "Muscle grows during rest. Breathe.",
  "Le plaisir d'abord, le chrono ensuite.": "Enjoyment first, the clock second.",
  "Le plus de répétitions possible, propres.": "As many clean reps as possible.",
  "le plus de reps possible, propres, en gardant 1 rep en réserve. C'est elle qui fait avancer le programme.": "as many clean reps as possible, keeping 1 rep in reserve. This is the set that moves the program forward.",
