  "Un Raccourci iOS envoie chaque matin ton sommeil, ta variabilité cardiaque (VFC), ta fréquence au repos, tes pas et ton poids. L'app préremplit ton bilan de forme avant chaque séance, ajoute tes pesées à ta courbe (calories adaptatives plus justes) et le coach en tient compte.": "An iOS Shortcut sends your sleep, heart rate variability (HRV), resting heart rate, steps and weight every morning. The app prefills your readiness check before each workout, adds your weigh-ins to your weight chart (more accurate adaptive calories) and the coach takes it all into account.",
